fixedSMTP={"ConnectTimeoutSeconds","CommandTimeoutSeconds","DeliveryTimeoutSeconds"}
fixedOperational={"MaintenanceEnabled","MaintenanceStartsAt","MaintenanceEndsAt","MaintenanceMessage","RegistrationEnabled","UploadsEnabled"}
counts=collections.Counter()
for row in data["parameters"]:
 row.update(expected_consumer="",actual_usage="",issue="",fix="",verification_scope="Static references only")
 field=row["id"].rsplit(".",1)[-1]
 if row["kind"]=="typed configuration field":
  for suffix,consumer,tests,status,note in families:
   if suffix in row["id"]:
    row.update(expected_consumer=consumer,actual_usage="Code-traced family; field-name reference candidates are not type-resolved proof.",verification=tests,status=status,verification_scope=note)
    break
  if not row["expected_consumer"]:
   row.update(expected_consumer="Declaring module → its constructor/composition and downstream owner",issue="No field-specific consumer acceptance recorded.",status="Partial")
  if "securitypolicy/policy.go::Policy." in row["id"]:
   row.update(issue="Persistence compared current ordinary bounds against fixed defaults.",fix="Use securitypolicy.Expiries with the current immutable policy snapshot.",actual_usage="Login, Google-link and password-change commit validation; same-transaction security recheck retained.")
  if "settings.go::SMTPConfiguration." in row["id"] and field in fixedSMTP:
   row.update(status="Fixed",issue="Saved SMTP budgets collapsed into their minimum; adapter rejected allowed command/overall ranges.",fix="Pass independent phase budgets through active delivery and tester; reset bounded deadlines.",verification="tests/identity/smtp_configured_timeouts_test.go")
  if "deliverysmtp/delivery.go::Config." in row["id"] and field in {"ConnectTimeout","CommandTimeout","DeliveryTimeout"}:
   row.update(status="Fixed",issue="One adapter timeout applied to all phases.",fix="Independent dial, command and overall deadlines, bounded by caller context.",verification="tests/identity/smtp_configured_timeouts_test.go")
  if "::PesaPalConfiguration.MerchantName" in row["id"]:
   row.update(status="Fixed",issue="Provider order description hardcoded Bidora instead of saved merchant name.",fix="Use exact pinned configuration merchant name.",verification="tests/platformsettings/pesapal_runtime_test.go")
  if "::OperationalPolicy." in row["id"] and field in fixedOperational:
   row.update(status="Fixed",issue="Case-sensitive/trailing-slash gate could disagree with case-insensitive router.",fix="Shared normalized path enforcement in request gate.",verification="tests/platformsettings/operational_gate_test.go")
  if "templates.go::Template." in row["id"] and field in {"Body","Subject","Version"}:
   row.update(status="Fixed",issue="Tenant invitation delivery did not resolve managed template.",fix="Enable managed tenant.invitation renderer in composed runtime; record actual template revision.",verification="tests/notification/tenant_template_settings_test.go")
  if "::OperationalPolicy.AIEnabled" in row["id"]: row.update(status="Working",verification="tests/platformsettings/openai_runtime_policy_test.go",verification_scope="Unit resolver global-disable/maintenance behavior; real AI request not executed.")
  if row["id"].endswith("pilot/runtime.go::Config.OpenAI") or ("::GoogleConfig." in row["id"] and field in {"ClientID","ClientSecret"}):
   row.update(status="Unused",issue="Retained deprecated compatibility field, not an active configuration source.",actual_usage="Intentionally ignored; managed DB/vault settings own runtime configuration.",verification_scope="Static composition trace, not a defect repaired by restoring legacy configuration.")
 elif row["kind"]=="environment name":
  row.update(expected_consumer="Deployment/example/command named references",actual_usage="See exact source references and scopes; direct references are not effective runtime acceptance.")
  if row["status"]=="Unused": row.update(status="Partial",issue="No directly resolved runtime reference; dynamic environment families, deployment-only and examples need explicit acceptance.")
  else: row["issue"]="Variable-specific effective runtime acceptance not established."
 elif row["kind"]=="configuration file directive":
  row.update(expected_consumer="Nginx/Next.js deployment or framework configuration",actual_usage="Parsed declaration; values intentionally omitted.",issue="Effective deployed directive not revalidated.",status="Partial")
 if row["status"]=="Fixed":
  row["actual_usage"]="Corrected consumer: "+row["expected_consumer"]+"; regression evidence in verification column."
 counts[row["status"]]+=1
data["status_definitions"]={"Working":"Relevant unit/fake behavior covered; verification_scope lists limits. Not live acceptance.","Fixed":"Confirmed integration defect corrected, with stated regression evidence.","Partial":"Static/mixed evidence; complete runtime acceptance not established.","Unused":"No runtime reference found, or explicitly deprecated; not necessarily a defect.","Broken":"Confirmed unresolved behavior defect."}
data["summary"]={"entries":len(data["parameters"]),"status":dict(counts),"kinds":dict(collections.Counter(x["kind"] for x in data["parameters"])),"coverage_warning":"Counts are source entries, including duplicate layer bindings, metadata and infrastructure; not unique business settings or verified end-to-end coverage."}
(target/"configuration-inventory.json").write_text(json.dumps(data,indent=2)+"\n")
columns=["id","kind","source","expected_consumer","actual_usage","status","issue","fix","verification","verification_scope","references"]
with (target/"configuration-matrix.csv").open("w",newline="") as f:
 writer=csv.DictWriter(f,fieldnames=columns,lineterminator="\n");writer.writeheader()
 for x in data["parameters"]:
  row={k:x.get(k,"") for k in columns};row["source"]=f'{x["source"]["path"]}:{x["source"]["line"]}';row["references"]="; ".join(f'{r["path"]}:{r["line"]} ({r["scope"]})' for r in (x.get("references") or [])[:20]); row["references"]+=(" [additional candidates in JSON]" if len(x.get("references") or [])>20 else "");writer.writerow(row)
print(json.dumps(data["summary"],indent=2))
